import sys
p, a, b = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
for i, l in enumerate(open(p, encoding="utf-8"), 1):
    if a <= i <= b:
        print(f"{i}: {l.rstrip()}")

import re, sys
p, pat = sys.argv[1], sys.argv[2]
for i, l in enumerate(open(p, encoding="utf-8"), 1):
    if re.search(pat, l):
        print(f"{i}: {l.rstrip()[:200]}")
